(function() {
  var STORAGE_KEY = 'cardspoke_card_templates';
  var PANEL_ID = 'cs-template-panel';
  var BTN_ID = 'cs-template-btn';
  var TEMPLATE_LIST_ID = 'cs-template-list';

  var templates = [];
  var isPanelOpen = false;

  var defaultTemplates = [
    {
      id: 'tpl-bug-report',
      name: 'Bug Report',
      category: 'Development',
      body: '## Bug Description\n\n{{description}}\n\n## Steps to Reproduce\n\n1. {{step1}}\n2. {{step2}}\n3. {{step3}}\n\n## Expected Behavior\n\n{{expected}}\n\n## Actual Behavior\n\n{{actual}}\n\n## Environment\n\n- OS: {{os}}\n- Browser: {{browser}}\n- Version: {{version}}',
      tags: ['bug-report'],
      createdAt: '2025-01-01T00:00:00Z'
    },
    {
      id: 'tpl-meeting-notes',
      name: 'Meeting Notes',
      category: 'Productivity',
      body: '## Meeting: {{title}}\n\n**Date:** {{date}}\n**Attendees:** {{attendees}}\n\n## Agenda\n\n- {{agenda_item}}\n\n## Discussion\n\n{{notes}}\n\n## Action Items\n\n- [ ] {{action}}\n\n## Next Steps\n\n{{next_steps}}',
      tags: ['meeting', 'notes'],
      createdAt: '2025-01-01T00:00:00Z'
    },
    {
      id: 'tpl-feature-request',
      name: 'Feature Request',
      category: 'Development',
      body: '## Feature: {{title}}\n\n## Problem Statement\n\n{{problem}}\n\n## Proposed Solution\n\n{{solution}}\n\n## User Stories\n\n- As a {{role}}, I want {{want}}, so that {{benefit}}\n\n## Acceptance Criteria\n\n- [ ] {{criteria}}\n\n## Priority\n\n{{priority}}',
      tags: ['feature-request'],
      createdAt: '2025-01-01T00:00:00Z'
    }
  ];

  function loadTemplates() {
    try {
      var saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        templates = JSON.parse(saved);
      } else {
        templates = defaultTemplates.slice();
        saveTemplates();
      }
    } catch (e) {
      console.warn('[Card Templates] Failed to load templates:', e);
      templates = defaultTemplates.slice();
    }
  }

  function saveTemplates() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(templates));
    } catch (e) {
      console.warn('[Card Templates] Failed to save templates:', e);
    }
  }

  function clearSavedTemplates() {
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch (e) {
      console.warn('[Card Templates] Failed to clear templates:', e);
    }
  }

  function generateId() {
    return 'tpl-' + Date.now().toString(36) + '-' + Math.random().toString(36).substr(2, 6);
  }

  function addTemplate(name, category, body, tags) {
    var template = {
      id: generateId(),
      name: name || 'Untitled Template',
      category: category || 'General',
      body: body || '',
      tags: tags || [],
      createdAt: new Date().toISOString()
    };
    templates.push(template);
    saveTemplates();
    renderTemplateList();
    return template;
  }

  function removeTemplate(templateId) {
    templates = templates.filter(function(t) { return t.id !== templateId; });
    saveTemplates();
    renderTemplateList();
  }

  function getTemplatesByCategory() {
    var categories = {};
    for (var i = 0; i < templates.length; i++) {
      var cat = templates[i].category || 'General';
      if (!categories[cat]) categories[cat] = [];
      categories[cat].push(templates[i]);
    }
    return categories;
  }

  function fillPlaceholders(body) {
    return body.replace(/\{\{(\w+)\}\}/g, function(match, key) {
      return '[' + key.replace(/_/g, ' ') + ']';
    });
  }

  function instantiateTemplate(templateId) {
    var template = null;
    for (var i = 0; i < templates.length; i++) {
      if (templates[i].id === templateId) {
        template = templates[i];
        break;
      }
    }
    if (!template) return null;
    return {
      title: template.name + ' - ' + new Date().toLocaleDateString(),
      body: fillPlaceholders(template.body),
      tags: template.tags.slice()
    };
  }

  function renderTemplateList() {
    var listEl = document.getElementById(TEMPLATE_LIST_ID);
    if (!listEl) return;
    var categories = getTemplatesByCategory();
    var html = '';
    var catKeys = Object.keys(categories).sort();
    for (var c = 0; c < catKeys.length; c++) {
      var catName = catKeys[c];
      var catTemplates = categories[catName];
      html += '<div style="margin-bottom:12px;"><div style="font-size:11px;font-weight:600;color:#888;text-transform:uppercase;margin-bottom:6px;padding:0 4px;">' + catName + '</div>';
      for (var t = 0; t < catTemplates.length; t++) {
        var tpl = catTemplates[t];
        html += '<div class="cs-tpl-item" data-tpl-id="' + tpl.id + '" style="display:flex;justify-content:space-between;align-items:center;padding:8px 10px;margin-bottom:4px;background:#f8f9fa;border:1px solid #eee;border-radius:6px;cursor:pointer;transition:background 0.15s;"><div><div style="font-size:13px;font-weight:500;color:#333;">' + tpl.name + '</div><div style="font-size:11px;color:#999;margin-top:2px;">' + (tpl.tags || []).join(', ') + '</div></div><div style="display:flex;gap:4px;"><button class="cs-tpl-use" data-tpl-id="' + tpl.id + '" style="padding:3px 8px;font-size:11px;background:#4a90d9;color:#fff;border:none;border-radius:4px;cursor:pointer;">Use</button><button class="cs-tpl-del" data-tpl-id="' + tpl.id + '" style="padding:3px 6px;font-size:11px;background:none;color:#ccc;border:1px solid #ddd;border-radius:4px;cursor:pointer;">x</button></div></div>';
      }
      html += '</div>';
    }
    if (templates.length === 0) {
      html = '<div style="text-align:center;padding:20px;color:#999;font-size:13px;">No templates yet. Save a card as a template to get started.</div>';
    }
    listEl.innerHTML = html;
    var useButtons = listEl.querySelectorAll('.cs-tpl-use');
    for (var u = 0; u < useButtons.length; u++) {
      useButtons[u].addEventListener('click', function(e) {
        e.stopPropagation();
        var id = this.getAttribute('data-tpl-id');
        var cardData = instantiateTemplate(id);
        if (cardData) {
          console.log('[Card Templates] Instantiated template:', cardData);
          document.dispatchEvent(new CustomEvent('cardspoke:createCard', { detail: cardData }));
        }
      });
    }
    var delButtons = listEl.querySelectorAll('.cs-tpl-del');
    for (var d = 0; d < delButtons.length; d++) {
      delButtons[d].addEventListener('click', function(e) {
        e.stopPropagation();
        var id = this.getAttribute('data-tpl-id');
        removeTemplate(id);
      });
    }
  }

  function createPanel() {
    if (document.getElementById(PANEL_ID)) return;
    var panel = document.createElement('div');
    panel.id = PANEL_ID;
    panel.style.cssText = 'position:fixed;top:60px;right:20px;width:320px;max-height:500px;background:#fff;border:1px solid #ddd;border-radius:10px;box-shadow:0 8px 30px rgba(0,0,0,0.12);z-index:9999;font-family:system-ui,-apple-system,sans-serif;display:none;flex-direction:column;overflow:hidden;';
    panel.innerHTML = '<div style="padding:12px 16px;border-bottom:1px solid #eee;display:flex;justify-content:space-between;align-items:center;"><span style="font-size:14px;font-weight:600;color:#333;">Card Templates</span><button id="cs-tpl-close" style="background:none;border:none;font-size:18px;color:#999;cursor:pointer;padding:0 4px;">&times;</button></div><div id="' + TEMPLATE_LIST_ID + '" style="padding:12px;overflow-y:auto;flex:1;"></div><div style="padding:10px 12px;border-top:1px solid #eee;"><button id="cs-tpl-add-current" style="width:100%;padding:8px;font-size:12px;background:#f0f0f0;border:1px solid #ddd;border-radius:6px;cursor:pointer;color:#555;">+ Save Current Card as Template</button></div>';
    document.body.appendChild(panel);
    document.getElementById('cs-tpl-close').addEventListener('click', togglePanel);
    document.getElementById('cs-tpl-add-current').addEventListener('click', function() {
      var name = prompt('Template name:');
      if (name) {
        var category = prompt('Category (e.g., Development, Productivity):') || 'General';
        addTemplate(name, category, '## ' + name + '\n\n{{content}}', []);
      }
    });
    renderTemplateList();
  }

  function createToggleButton() {
    if (document.getElementById(BTN_ID)) return;
    var btn = document.createElement('button');
    btn.id = BTN_ID;
    btn.textContent = 'Templates';
    btn.style.cssText = 'position:fixed;bottom:20px;left:20px;padding:8px 16px;background:#4a90d9;color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:500;cursor:pointer;z-index:9998;box-shadow:0 2px 10px rgba(74,144,217,0.3);transition:background 0.2s;';
    btn.addEventListener('click', togglePanel);
    btn.addEventListener('mouseenter', function() { btn.style.background = '#3a7bc8'; });
    btn.addEventListener('mouseleave', function() { btn.style.background = '#4a90d9'; });
    document.body.appendChild(btn);
  }

  function togglePanel() {
    var panel = document.getElementById(PANEL_ID);
    if (!panel) return;
    isPanelOpen = !isPanelOpen;
    panel.style.display = isPanelOpen ? 'flex' : 'none';
    if (isPanelOpen) renderTemplateList();
  }

  function destroyUI() {
    var panel = document.getElementById(PANEL_ID);
    if (panel) panel.parentNode.removeChild(panel);
    var btn = document.getElementById(BTN_ID);
    if (btn) btn.parentNode.removeChild(btn);
    isPanelOpen = false;
  }

  CardSpoke_MODS.register({
    name: 'Card Templates',
    hooks: {
      onAppInit: function() {
        loadTemplates();
        createPanel();
        createToggleButton();
        console.log('[Card Templates] Mod initialized with', templates.length, 'templates');
      },
      onCardRender: function(cardData) {
        if (cardData && cardData.element) {
          var saveBtn = cardData.element.querySelector('.cs-tpl-save-btn');
          if (!saveBtn) {
            var actions = cardData.element.querySelector('.cs-card-actions, .card-actions');
            if (actions) {
              var btn = document.createElement('button');
              btn.className = 'cs-tpl-save-btn';
              btn.textContent = 'Save as Template';
              btn.style.cssText = 'padding:3px 8px;font-size:11px;background:none;border:1px solid #ddd;border-radius:4px;color:#888;cursor:pointer;margin-left:4px;';
              btn.addEventListener('click', function() {
                var name = prompt('Template name:');
                if (name && cardData.body) {
                  addTemplate(name, 'Custom', cardData.body, cardData.tags || []);
                }
              });
              actions.appendChild(btn);
            }
          }
        }
      },
      onDisable: function() {
        destroyUI();
        console.log('[Card Templates] Mod disabled, UI removed');
      },
      onUninstall: function() {
        destroyUI();
        clearSavedTemplates();
        console.log('[Card Templates] Mod uninstalled, all data cleared');
      }
    }
  });
})()
